begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('34000000-0000-4000-8000-000000000001','stock-staff@example.test','{}'),('34000000-0000-4000-8000-000000000002','stock-inactive@example.test','{}');
update public.profiles set is_active = true where id in ('34000000-0000-4000-8000-000000000001','34000000-0000-4000-8000-000000000002');
insert into public.user_roles (user_id, role) values ('34000000-0000-4000-8000-000000000001','STAFF'),('34000000-0000-4000-8000-000000000002','STAFF');

insert into auth.users(id,email,raw_user_meta_data) values('34000000-0000-4000-8000-000000000003','other-active@example.test','{}');
update public.profiles set is_active = true where id in ('34000000-0000-4000-8000-000000000003');
insert into public.user_roles (user_id, role) values ('34000000-0000-4000-8000-000000000003','STAFF');

update public.profiles set is_active=false where id='34000000-0000-4000-8000-000000000002';
create temp table fx(k text primary key,id uuid); grant all on fx to authenticated;
create temp table requests(k text primary key,v jsonb); grant all on requests to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"34000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from public.save_client(auth.uid(),null,null,'Stock','Family',null,null,'EMAIL',null,null);
insert into fx select 'pet',id from public.save_patient(null,(select id from fx where k='client'),null,'Stockdog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'product',id from public.save_catalog_product(null,null,'Rabies vaccine','vaccine','Manufacturer','dose',3500,true);
insert into fx select 'service',id from public.save_catalog_product(null,null,'Exam','service','','visit',9000,true);
select lives_ok($$select public.receive_inventory('35000000-0000-4000-8000-000000000001','35000000-0000-4000-8000-000000000002',(select id from fx where k='product'),'LOT-1',current_date+365,'Clinic',10,'Opening stock')$$,'Receive vaccine stock');
select lives_ok($$select public.receive_inventory('35000000-0000-4000-8000-000000000001','35000000-0000-4000-8000-000000000002',(select id from fx where k='product'),'LOT-1',current_date+365,'Clinic',10,'Opening stock')$$,'Receipt retry idempotent');
select is((select sum(quantity) from public.inventory_movements),10::numeric,'Retry does not duplicate stock');
select throws_ok($$select public.receive_inventory('35000000-0000-4000-8000-000000000001','35000000-0000-4000-8000-000000000002',(select id from fx where k='product'),'LOT-1',current_date+365,'Clinic',11,'Opening stock')$$,'23514',null,'Receipt retry cannot change quantity');
select throws_ok($$select public.adjust_inventory(gen_random_uuid(),'35000000-0000-4000-8000-000000000002',-11,'Count correction')$$,'23514','Insufficient stock','Adjustment cannot make stock negative');
select lives_ok($$select public.create_billing_invoice('35000000-0000-4000-8000-000000000003',(select id from fx where k='client'))$$,'Create draft invoice');
select throws_ok($$select public.issue_billing_invoice('35000000-0000-4000-8000-000000000003',1)$$,'23514',null,'Empty invoice cannot issue');
insert into requests values('live',jsonb_build_object('pet_id',(select id from fx where k='pet'),'lot_id','35000000-0000-4000-8000-000000000002','invoice_id','35000000-0000-4000-8000-000000000003','quantity',1,'dose','1 mL','route','SC','site','right rear leg','veterinarian','Dr Test','veterinarian_license','TEST-ONLY','administered_at',now(),'next_due_on',current_date+365));
update requests set v=v||jsonb_build_object('alert_review',jsonb_build_object('source_hash',read_patient_treatment_alerts((v->>'pet_id')::uuid)->>'source_hash','acknowledged',true)) where k='live';

select throws_ok($$select record_patient_treatment(gen_random_uuid(),(select v-'alert_review' from requests where k='live'))$$,'23514',null,'Direct treatment bypass without review denied');
select throws_ok($$select record_patient_treatment(gen_random_uuid(),(select jsonb_set(v,'{alert_review,acknowledged}','false') from requests where k='live'))$$,'23514',null,'False acknowledgment denied');
select throws_ok($$select record_patient_treatment(gen_random_uuid(),(select jsonb_set(v,'{alert_review,actor_id}',to_jsonb(auth.uid()::text)) from requests where k='live'))$$,'23514',null,'Caller cannot supply review actor metadata');
select is((select count(*) from billing_invoice_items),0::bigint,'Bypass leaves no billing writes');
select is((select sum(quantity) from inventory_movements),10::numeric,'Bypass leaves stock unchanged');
insert into fx select 'problem',id from save_patient_problem(null,(select id from fx where k='pet'),null,'Prior vaccine reaction','Important historical context',(now() at time zone 'America/Denver')::date,'resolved','high');
select is(read_patient_treatment_alerts((select id from fx where k='pet'))#>>'{snapshot,important_problems,0,status}','resolved','Resolved critical history remains in reviewed content');
select throws_ok($$select record_patient_treatment(gen_random_uuid(),(select v from requests where k='live'))$$,'40001',null,'New flag invalidates old empty-alert review');
update requests set v=v||jsonb_build_object('alert_review',jsonb_build_object('source_hash',read_patient_treatment_alerts((v->>'pet_id')::uuid)->>'source_hash','acknowledged',true)) where k='live';
select lives_ok($$select record_patient_treatment('35000000-0000-4000-8000-000000000004',(select v from requests where k='live'))$$,'Reviewed administration commits');
select is((select reviewed_by from treatment_alert_reviews where treatment_id='35000000-0000-4000-8000-000000000004'),auth.uid(),'Review actor stamped from session');
select is((select snapshot#>>'{important_problems,0,title}' from treatment_alert_reviews),'Prior vaccine reaction','Exact important history frozen with treatment');
reset role;
select is((select count(*) from audit_logs where table_name='treatment_alert_reviews'),1::bigint,'Review association audited');
set local role authenticated;
select save_patient_problem((select id from fx where k='problem'),(select id from fx where k='pet'),1,'Prior vaccine reaction','Updated reaction details',(now() at time zone 'America/Denver')::date,'resolved','high');
select throws_ok($$select record_patient_treatment(gen_random_uuid(),(select v from requests where k='live'))$$,'40001',null,'Changed alert details reject a new treatment');
select lives_ok($$select record_patient_treatment('35000000-0000-4000-8000-000000000004',(select v from requests where k='live'))$$,'Committed response-loss retry succeeds despite later alerts');
select is((select count(*) from treatment_alert_reviews),1::bigint,'Retry does not duplicate review association');
select is((select count(*) from billing_invoice_items),1::bigint,'Retry does not duplicate charge');
select is((select sum(quantity) from inventory_movements),9::numeric,'Retry does not double-debit stock');
select throws_ok($$update treatment_alert_reviews set source_hash=repeat('a',64)$$,'42501',null,'Staff cannot alter review history');
select throws_ok($$delete from treatment_alert_reviews$$,'42501',null,'Staff cannot delete review history');
select throws_ok($$insert into treatment_alert_reviews select * from treatment_alert_reviews$$,'42501',null,'Staff cannot fabricate review associations');
reset role;
select throws_ok($$update treatment_alert_reviews set source_hash=repeat('a',64)$$,'23514',null,'Even direct privileged mutation is immutable');
update pets set allergies='Legacy reaction text' where id=(select id from fx where k='pet');
set local role authenticated;
select is(read_patient_treatment_alerts((select id from fx where k='pet'))#>>'{snapshot,legacy_allergies,text}','Legacy reaction text','Legacy allergy text included');
select ok(read_patient_treatment_alerts((select id from fx where k='pet'))#>>'{snapshot,legacy_allergies,provenance}' like '%not established%','Legacy verification uncertainty preserved');
select throws_ok($$select record_patient_treatment(gen_random_uuid(),(select v from requests where k='live'))$$,'40001',null,'Allergy change rejects stale review');
select lives_ok($$select record_patient_treatment('35000000-0000-4000-8000-000000000009',jsonb_build_object('pet_id',(select id from fx where k='pet'),'historical',true,'quantity',1,'product_name','External medication','manufacturer','External','lot_number','Unknown','dose','Unknown','route','Unknown','veterinarian','Source veterinarian unknown','administered_at',now()-interval '1 year','source','Historical source transcription'))$$,'Historical transcription does not claim current-care review');
select is((select count(*) from treatment_alert_reviews),1::bigint,'No fabricated acknowledgment on historical transcription');
select set_config('request.jwt.claims','{"sub":"34000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select record_patient_treatment('35000000-0000-4000-8000-000000000004',(select v from requests where k='live'))$$,'23514',null,'Another active actor cannot replay original reviewed treatment');
select set_config('request.jwt.claims','{"sub":"34000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select read_patient_treatment_alerts((select id from fx where k='pet'))$$,'42501',null,'Inactive staff cannot read alert review');
select throws_ok($$select record_patient_treatment('35000000-0000-4000-8000-000000000004',(select v from requests where k='live'))$$,'42501',null,'Inactive actor cannot recover another treatment');
select is((select count(*) from treatment_alert_reviews),0::bigint,'Inactive staff cannot read review history');
reset role;set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select read_patient_treatment_alerts(null)$$,'42501',null,'Service role cannot impersonate clinical review');
reset role;set local role anon;
select throws_ok($$select read_patient_treatment_alerts(null)$$,'42501',null,'Anonymous alert access denied');
select * from finish();
rollback;
